"use strict";
$(function() {
	if ($(".J_wheel").length) {
		var e = {
			counter: 0,
			innerAngel: 0,
			outerAngel: 0,
			sx: 0,
			tagList: ["合太岁年", "犯太岁年", "吉星飞临", "吉星欠奉", "破太岁年", "吉星驾临", "害太岁年", "冲太岁年", "吉星临门", "流年半合", "刑太岁年", "吉星相助"],
			timer: null,
			rotate: function() {
				e.innerAngel = e.innerAngel + 480;
				var t = Math.floor(10 * Math.random()) + 10;
				e.sx = e.sx + t, e.outerAngel = e.outerAngel + 30 * t, $(".J_wheel_inner").css({
					transform: "rotate(" + e.innerAngel + "deg)",
					"-webkit-transform": "rotate(" + e.innerAngel + "deg)",
					"-moz-transform": "rotate(" + e.innerAngel + "deg)",
					"-ms-transform": "rotate(" + e.innerAngel + "deg)",
					"-o-transform": "rotate(" + e.innerAngel + "deg)"
				}), $(".J_wheel_outer").css({
					transform: "rotate(-" + e.outerAngel + "deg)",
					"-webkit-transform": "rotate(-" + e.outerAngel + "deg)",
					"-moz-transform": "rotate(-" + e.outerAngel + "deg)",
					"-ms-transform": "rotate(-" + e.outerAngel + "deg)",
					"-o-transform": "rotate(-" + e.outerAngel + "deg)"
				}), setTimeout(function() {
					$(".J_wheel_outer>span").eq((e.sx + 1) % 12).addClass("active")
				}, 2200), setTimeout(function() {
					$(".J_wheel_tag").text(e.tagList[(e.sx + 1) % 12]).fadeIn()
				}, 4e3), setTimeout(function() {
					$(".J_wheel_outer>.active").removeClass("active")
				}, 5800), setTimeout(function() {
					$(".J_wheel_tag").hide()
				}, 5800), e.counter++
			},
			init: function() {
				setTimeout(function() {
					e.rotate(), e.timer = setInterval(function() {
						e.rotate()
					}, 6e3)
				}, 2e3)
			}
		};
		e.init(), document.addEventListener("visibilitychange", function() {
			"hidden" == document.visibilityState ? clearInterval(e.timer) : e.init()
		}), $(".J_index_step1_btn").on("click", function() {
			$(".J_index_step1").hide(), $(".J_index_step2").show()
		})
	}
	if ($(".J_order_wheel").length) {
		var t = ["甲", "乙", "丙", "丁", "戊", "己", "庚", "辛", "壬", "癸"],
			o = ["子", "丑", "寅", "卯", "辰", "巳", "午", "未", "申", "酉", "戌", "亥"],
			n = $(".J_order_wheel_inner").data("inner"),
			r = $(".J_order_wheel_outer").data("outer"),
			i = t.indexOf(n),
			a = o.indexOf(r);
		$(".J_bar1").addClass("active");
		for (var s = 1; s < 11; s++)!
		function(e) {
			setTimeout(function() {
				$(".J_order_wheel_inner>span").eq(e - 1).addClass("active")
			}, 300 * e)
		}(s);
		setTimeout(function() {
			var e = 30 * a,
				t = e + 3 - 36 * i - 2160;
			$(".J_order_wheel_inner").css({
				transform: "rotate(" + t + "deg)",
				"-webkit-transform": "rotate(" + t + "deg)",
				"-moz-transform": "rotate(" + t + "deg)",
				"-ms-transform": "rotate(" + t + "deg)",
				"-o-transform": "rotate(" + t + "deg)"
			});
			for (var o = 1; o < 13; o++)!
			function(e) {
				setTimeout(function() {
					$(".J_order_wheel_outer>span").eq(e - 1).addClass("active")
				}, 300 * e)
			}(o);
			setTimeout(function() {
				$(".J_order_wheel_outer").addClass("active")
			}, 3900)
		}, 3300), setTimeout(function() {
			$(".J_order_wheel_inner>span").eq(i).addClass("selected"), $(".J_order_wheel_outer>span").eq(a).addClass("selected"), $(".J_order_info1").hide(), $(".J_order_info2").show(), $(".J_bar2").addClass("active");
			for (var e = 1; e < 13; e++)!
			function(e) {
				setTimeout(function() {
					$(".J_order_wheel_middle>span").eq(e - 1).addClass("active")
				}, 300 * e)
			}(e);
			setTimeout(function() {
				$(".J_order_wheel_middle").addClass("active"), setTimeout(function() {
					$(".J_order_wheel_middle>span").eq(a).addClass("selected")
				}, 3e3)
			}, 3900)
		}, 11e3), setTimeout(function() {
			$(".J_bar3").addClass("active");
			for (var e = [1, 4, 6, 7, 10], t = 0; t < e.length; t++)!
			function(t) {
				setTimeout(function() {
					$(".J_order_wheel_middle>span").eq(e[t]).addClass("fan")
				}, 300 * t)
			}(t);
			setTimeout(function() {
				$(".J_order_wheel_niu").removeClass("active"), $(".J_order_info2").hide(), $(".J_order_info").show()
			}, 3900)
		}, 18e3);
		var l = 0;
		$(".J_showPayBtn").on("click", function() {
			l = $(document).scrollTop(), $("body").css({
				position: "fixed",
				top: -l
			}), $(".J_order_pay").fadeIn()
		}), $(".J_order_pay").on("click", function() {
			$("body").css({
				position: "static"
			}), $(document).scrollTop(l), $(".J_order_pay").hide()
		}), $(".J_order_pay>div").on("click", function(e) {
			e.stopPropagation()
		})
	}
	if ($("#charts").length) {
		var d = $("#charts").data("source"),
			c = [];
		d.forEach(function(e, t) {
			c.push({
				month: t + 1,
				value: e.total
			})
		}), require(["ffsm-echarts"], function(e) {
			var t = e.init($("#charts").get(0)),
				o = {
					title: {
						text: "月运走势图",
						left: "center"
					},
					grid: {
						top: 50,
						left: "3%",
						right: 20,
						bottom: 10,
						containLabel: !0
					},
					xAxis: {
						type: "category",
						boundaryGap: !1,
						axisLine: {
							lineStyle: {
								color: "#e8e1dc"
							}
						},
						axisTick: {
							show: !1
						},
						splitLine: {
							show: !0,
							lineStyle: {
								color: "#e8e1dc"
							}
						},
						axisLabel: {
							color: "#333",
							fontSize: 16
						}
					},
					yAxis: {
						type: "value",
						min: -6,
						max: 6,
						axisLine: {
							lineStyle: {
								color: "#e8e1dc"
							}
						},
						axisTick: {
							show: !1
						},
						splitLine: {
							lineStyle: {
								color: "#e8e1dc"
							}
						},
						axisLabel: {
							formatter: function(e) {
								var t = [];
								return 0 == e ? t.push("平") : -6 == e ? t.push("凶") : 6 == e ? t.push("吉") : t.push(""), t
							},
							color: "#bf1b11",
							fontSize: 16
						}
					},
					series: [{
						type: "line",
						smooth: !0,
						symbolSize: 3,
						itemStyle: {
							color: "#f06559"
						},
						lineStyle: {
							color: "#bf1b11"
						},
						encode: {
							x: "month",
							y: "value"
						}
					}],
					dataset: {
						dimensions: ["month", "value"],
						source: c
					}
				};
			t.setOption(o), $(window).resize(function() {
				t.resize()
			})
		})
	}
});